import sys

def main():
    n = int(sys.stdin.readline())
    current_time = 0

    for _ in range(n):
        travel, period, window, offset = map(
            int, sys.stdin.readline().split()
        )

        current_time += travel

        phase = (current_time - offset) % period

        if phase >= window:
            current_time += period - phase

    print(current_time)

if __name__ == "__main__":
    main()
